import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"What is a Mod","description":"","frontmatter":{"title":"What is a Mod","order":2},"headers":[],"relativePath":"learn/mod/what-is-mod.md","filePath":"learn/mod/what-is-mod.md","lastUpdated":1786943111000}'),i={name:"learn/mod/what-is-mod.md"};function d(s,a,n,l,h,m){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="what-is-a-mod" tabindex="-1">What is a Mod <a class="header-anchor" href="#what-is-a-mod" aria-label="Permalink to &quot;What is a Mod&quot;">​</a></h1><p>A Mod is a modification to a game. In ADOFAI, Mods usually exist as <strong>UnityModManager (UMM)</strong> plugins that extend the game&#39;s behavior, visuals, and data.</p><h2 id="what-mods-can-do" tabindex="-1">What Mods Can Do <a class="header-anchor" href="#what-mods-can-do" aria-label="Permalink to &quot;What Mods Can Do&quot;">​</a></h2><p>Examples from real projects in this organization:</p><table tabindex="0"><thead><tr><th>Mod</th><th>What it does</th></tr></thead><tbody><tr><td><a href="https://github.com/adofaiex/Iridium" target="_blank" rel="noreferrer">Iridium</a></td><td>Optimization Mod for ADOFAI, improves performance</td></tr><tr><td><a href="https://github.com/adofaiex/YqlossClientHarmony" target="_blank" rel="noreferrer">YqlossClientHarmony</a></td><td>Fixes fatal decorations, effect removal, replay recording</td></tr><tr><td><a href="https://github.com/adofaiex/Iris" target="_blank" rel="noreferrer">Iris</a></td><td>Provides visual effects for the game</td></tr><tr><td><a href="https://github.com/adofaiex/JipperKeyViewer" target="_blank" rel="noreferrer">JipperKeyViewer</a></td><td>Key viewer</td></tr><tr><td><a href="https://github.com/adofaiex/ADOFAI.EditorTweaks" target="_blank" rel="noreferrer">ADOFAI.EditorTweaks</a></td><td>Editor enhancements</td></tr></tbody></table><h2 id="how-mods-work" tabindex="-1">How Mods Work <a class="header-anchor" href="#how-mods-work" aria-label="Permalink to &quot;How Mods Work&quot;">​</a></h2><p>The vast majority of ADOFAI Mods rely on two things:</p><ol><li><strong>UnityModManager (UMM)</strong> — loads Mods, manages enable/disable, provides a settings UI</li><li><strong>Harmony</strong> — a runtime patching library that can intercept and modify game methods without touching the game&#39;s source code</li></ol><h2 id="what-you-can-build" tabindex="-1">What You Can Build <a class="header-anchor" href="#what-you-can-build" aria-label="Permalink to &quot;What You Can Build&quot;">​</a></h2><p>With these two tools, you can build a rich variety of features:</p><ul><li>Remove or add visual effects</li><li>Recording and replay</li><li>Performance optimization</li><li>Draw in-game UI</li><li>Extend the editor&#39;s capabilities</li></ul><div class="warning custom-block"><p class="custom-block-title">Red lines</p><p>Please do NOT create Mods that <strong>break the vanilla game&#39;s balance</strong> (e.g. altering hit judgement or accuracy calculation). The game&#39;s judgement system is officially off-limits, and this tutorial will not cover such practices. See <a href="./guidelines">Mod Development Guidelines</a> for more.</p></div><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>With your environment ready, write your first Mod → <a href="./first-mod">Minimal Example</a></p>',14)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
